pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }
    function testRegression_property() public {
        address[] memory tos = new address[](1);
        tos[0] = address(0x1);
        uint[] memory vs = new uint[](1);
        vs[0] = 1;
        bool ok;
        try c.transfer(address(0x0), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
